@page "/board"
@using sv_84657f2dd452416380398f6edea4ef11.Components.Pages.Board
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (isLoading)
{
    <div class="text-center py-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
        <p class="mt-2 text-muted">Loading tasks...</p>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-outline-danger btn-sm ms-2" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardStats Tasks="tasks" />
    <BoardSearch SearchText="@searchText" OnSearchChanged="HandleSearchChanged" />

    <div class="row g-3">
        @for (var i = 0; i < columns.Length; i++)
        {
            var col = columns[i];
            var columnTasks = FilteredTasks.Where(t => t.Status == col.Status).ToList();

            <KanbanColumn Title="@col.Name"
                          Status="@col.Status"
                          Tasks="columnTasks"
                          ColumnIndex="i"
                          ColumnCount="@columns.Length"
                          OnTaskMoved="HandleTaskMoved"
                          OnTaskCreated="HandleTaskCreated" />
        }
    </div>
}

@code {
    private readonly record struct ColumnDef(string Name, string Status);

    private static readonly ColumnDef[] columns =
    [
        new("To Do", "To Do"),
        new("In Progress", "In Progress"),
        new("Done", "Done")
    ];

    private List<TaskItem> tasks = [];
    private string searchText = "";
    private bool isLoading = true;
    private string? errorMessage;

    private IEnumerable<TaskItem> FilteredTasks =>
        string.IsNullOrWhiteSpace(searchText)
            ? tasks
            : tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private void HandleSearchChanged(string value)
    {
        searchText = value;
    }

    private async Task HandleTaskMoved((int TaskId, int Direction) move)
    {
        var task = tasks.FirstOrDefault(t => t.Id == move.TaskId);
        if (task is null) return;

        var currentIndex = Array.FindIndex(columns, c => c.Status == task.Status);
        var newIndex = currentIndex + move.Direction;
        if (newIndex < 0 || newIndex >= columns.Length) return;

        var newStatus = columns[newIndex].Status;

        try
        {
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            // Replace the task in the list with the updated status
            var idx = tasks.IndexOf(task);
            tasks[idx] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private void HandleTaskCreated(TaskItem task)
    {
        tasks.Add(task);
    }
}

