     private string? errorMessage;

     private IEnumerable<TaskItem> FilteredTasks =>
         string.IsNullOrWhiteSpace(searchText)
             ? tasks
             : tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));

